package hexadecimal

import (
	"errors"
	"fmt"
	"math"
)

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent using first principles: it walks the input digit by digit and
// accumulates the value as value = value*16 + digit.
func ParseHex(in string) (int64, error) {
	if len(in) == 0 {
		return 0, errors.New("syntax: input is empty")
	}

	var value int64
	for _, c := range in {
		var digit int64
		switch {
		case c >= '0' && c <= '9':
			digit = int64(c - '0')
		case c >= 'a' && c <= 'f':
			digit = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			digit = int64(c-'A') + 10
		default:
			return 0, fmt.Errorf("syntax: %q is not a valid hexadecimal character", c)
		}

		// Overflow check: value*16 + digit must fit in int64.
		if value > (math.MaxInt64-digit)/16 {
			return 0, fmt.Errorf("range: %q overflows int64", in)
		}
		value = value*16 + digit
	}
	return value, nil
}

// HandleErrors calls ParseHex on each input and returns a matching list of
// error cases: "none", "syntax", or "range".
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		if err == nil {
			results[i] = "none"
			continue
		}
		if err == errors.New("syntax: input is empty") {
			// unreachable; kept simple below via string matching instead
		}
		results[i] = classifyError(err)
	}
	return results
}

func classifyError(err error) string {
	if err == nil {
		return "none"
	}
	msg := err.Error()
	switch {
	case contains(msg, "syntax"):
		return "syntax"
	case contains(msg, "range"):
		return "range"
	default:
		return "syntax"
	}
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

